from pysat import formula
from pysat.solvers import Glucose3

n_pigeons = 15
n_holes = 14

f = formula.CNF()

# Each pigeon in at least one hole
for i in range(n_pigeons):
    clause = [i*n_holes + j + 1 for j in range(n_holes)]
    f.append(clause)

# Each pigeon in at most one hole
for i in range(n_pigeons):
    for j1 in range(n_holes):
        for j2 in range(j1+1, n_holes):
            f.append([-(i*n_holes + j1 + 1), -(i*n_holes + j2 + 1)])

# Each hole at most one pigeon
for j in range(n_holes):
    for i1 in range(n_pigeons):
        for i2 in range(i1+1, n_pigeons):
            f.append([-(i1*n_holes + j + 1), -(i2*n_holes + j + 1)])

solver = Glucose3()
solver.append_formula(f)
result = solver.solve()
print("Satisfiable:", result)
